# Run from the package root after data-raw/dat/build_dat.R and 54b:  Rscript data-raw/qa/57_dat_section.R
# Writes the section "NWS damage-survey data (DAT)" of data-raw/known_issues.md (between <!-- dat:start --> and <!-- dat:end -->): what the layers hold, how the fields are filled, how many SPC tornadoes have a linked
# survey line by year, and the distribution of the link numbers. Everything is computed from the data in data/ and, for the NCEI comparison of event_id, from the saved NCEI files of 54b.
suppressMessages({library(sf); library(dplyr)}); source("data-raw/qa/helpers.R"); for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x); q2 <- function(x, p = c(.5, .9, .99, 1)) paste(sprintf("%.2f", quantile(x, p, na.rm = TRUE, names = FALSE)), collapse = " / ")
md <- function(df) { df[] <- lapply(df, as.character); paste(c(paste0("| ", paste(names(df), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|"), apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n") }
L <- st_drop_geometry(dat_lines); P <- st_drop_geometry(dat_polygons); Q <- st_drop_geometry(dat_points)
yr <- function(x) as.integer(format(x$stormdate_utc, "%Y")); fetch <- readRDS("data-raw/dat/fetch/fetch_summary.rds"); bs <- readRDS("data-raw/dat/fetch/build_summary.rds")
cnt <- data.frame(Layer = c("Damage points", "Damage lines", "Damage polygons"), Features = f0(c(nrow(Q), nrow(L), nrow(P))), Fields = c(sum(!grepl("_utc$", names(Q))), sum(!grepl("_utc$", names(L))), sum(!grepl("_utc$", names(P)))), `Empty geometry` = f0(bs$empty), `No stormdate` = f0(bs$no_date),
  `Dated before 2007` = f0(c(sum(yr(Q) < 2007, na.rm = TRUE), sum(yr(L) < 2007, na.rm = TRUE), sum(yr(P) < 2007, na.rm = TRUE))), `Size of the service's response` = sprintf("%.1f MB", fetch$json_mb[order(fetch$layer)]), check.names = FALSE)
cnt <- cnt[, c(1, 2, 4, 5, 6, 7)]
yrs <- 2007:max(yr(L), na.rm = TRUE); ty <- as.integer(substr(tornado_tracks$tornado_id, 1, 4)); linked <- unique(tornado_dat_link$tornado_id)
by_year <- do.call(rbind, lapply(yrs, function(y) data.frame(Year = y, `DAT points` = f0(sum(yr(Q) == y, na.rm = TRUE)), `DAT lines` = f0(sum(yr(L) == y, na.rm = TRUE)), `DAT polygons` = f0(sum(yr(P) == y, na.rm = TRUE)), `SPC tornadoes` = f0(sum(ty == y)), `with a linked line` = f0(sum(tornado_tracks$tornado_id[ty == y] %in% linked)), Share = if (sum(ty == y) > 0) pc(mean(tornado_tracks$tornado_id[ty == y] %in% linked)) else "none (no SPC tornadoes)", check.names = FALSE)))
ef <- function(x) { x <- ifelse(is.na(x), "(missing)", x); t <- sort(table(x), decreasing = TRUE); paste0("`", names(t), "` ", f0(as.integer(t)), collapse = ", ") }
eid <- function(x) { x <- x[!is.na(x) & nzchar(x)]; c(filled = length(x), numeric = sum(grepl("^[0-9]+$", x)), distinct = length(unique(x)), duplicated = sum(duplicated(x))) }
e <- list(points = eid(Q$event_id), lines = eid(L$event_id), polygons = eid(P$event_id)); n <- c(nrow(Q), nrow(L), nrow(P))
nc <- readRDS(qa_out("ncei_comparison.rds")); Nid <- as.character(nc$N$EVENT_ID); ids <- unique(c(Q$event_id, L$event_id, P$event_id)); ids <- ids[!is.na(ids) & nzchar(ids)]
lk <- tornado_dat_link; pl <- dat_polygon_line_link
rule_tab <- data.frame(Rule = names(table(lk$rule)), Links = f0(as.integer(table(lk$rule))), check.names = FALSE)
txt <- c("<!-- dat:start -->", "## NWS damage-survey data (DAT)", "",
 paste0("The three layers of the Damage Assessment Toolkit service were fetched whole on ", readLines("data-raw/dat/access_date.txt"), " (no date filter, all fields, full resolution, EPSG:4326). The counts below equal the counts the service reported. Operations on the features: none."), "", md(cnt), "",
 paste0("**Dates.** The service gives dates as milliseconds since 1970-01-01 UTC, as text; they are stored as numbers with a `_utc` copy. The earliest `stormdate` is ", format(min(c(L$stormdate_utc, P$stormdate_utc, Q$stormdate_utc), na.rm = TRUE), "%Y-%m-%d"), " and the latest ", format(max(c(L$stormdate_utc, P$stormdate_utc, Q$stormdate_utc), na.rm = TRUE), "%Y-%m-%d"), "; features before 1996 cannot be linked to an SPC tornado."), "",
 paste0("**Rating field.** The values of `efscale` are those the survey teams entered. Polygons: ", ef(P$efscale), ". Lines: ", ef(L$efscale), ". Points: ", ef(Q$efscale), "."), "",
 paste0("**`event_id`** is free text. Filled: points ", f0(e$points[["filled"]]), " of ", f0(n[1]), " (", pc(e$points[["filled"]] / n[1], 0), "), lines ", f0(e$lines[["filled"]]), " of ", f0(n[2]), " (", pc(e$lines[["filled"]] / n[2], 0), "), polygons ", f0(e$polygons[["filled"]]), " of ", f0(n[3]), " (", pc(e$polygons[["filled"]] / n[3], 0), "). Only ", pc(e$lines[["numeric"]] / e$lines[["filled"]], 0), " of the line values are numbers, and ", f0(e$lines[["duplicated"]]), " line values are repeated. Of the ", f0(length(ids)), " distinct values, ", f0(sum(ids %in% Nid)), " equals the event id of a tornado in NCEI's Storm Events database (2007 to 2025): it is not an NCEI event id and it does not link the layers reliably, so the package does not use it."), "",
 "**By year, with the SPC tornadoes that have a linked survey line** (a survey is not available for every tornado; coverage grows over the years):", "", md(by_year), "",
 paste0("**The link table.** ", f0(nrow(lk)), " of ", f0(nrow(L)), " lines are linked to ", f0(length(linked)), " tornadoes, by these rules:"), "", md(rule_tab), "",
 paste0("Distribution of the link numbers (median / 90th percentile / 99th percentile / maximum): index-aligned distance ", q2(lk$index_aligned_dist_km), " km; one-sided distance ", q2(lk$one_sided_dist_km), " km; length ratio (DAT length over SPC length) ", q2(lk$length_ratio), "; `same_state` is FALSE for ", f0(sum(!lk$same_state, na.rm = TRUE)), " links. The same numbers for the mutual-closest links only: index-aligned distance ", q2(lk$index_aligned_dist_km[lk$rule == "mutual_closest"]), " km. `tornado_dat_link` has no cutoff, so a link can be to a line far from the tornado; filter on the distance columns for your purpose."), "",
 paste0("**Polygons and lines.** `dat_polygon_line_link` has ", f0(nrow(pl)), " rows (", f0(sum(pl$line_share_in_polygon > 0)), " with the line touching the polygon). ", f0(length(unique(pl$dat_polygon_id[pl$line_share_in_polygon > 0 & pl$dat_line_id %in% lk$dat_line_id]))), " of the ", f0(nrow(P)), " polygons touch a linked line; polygons are nested by rating, so they overlap one another (the sum of the polygon areas is larger than the area they cover)."), "",
 paste0("**Linkage not made.** ", f0(sum(!dat_lines$objectid %in% lk$dat_line_id)), " lines are in no link: ", f0(bs$lines_not_linkable[["empty"]]), " have an empty geometry, ", f0(bs$lines_not_linkable[["no_date"]]), " have no date, and the rest have no SPC tornado within a day, or their one-sided nearest tornado has no mutual-closest line. Damage points are not linked to tornadoes by any rule."), "",
 "<!-- dat:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- dat:start -->", kl, fixed = TRUE); b <- grep("<!-- dat:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("^## Notices about the Damage", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
